  const blocking = axes.some((a) => a.status === "fail");
  const grade = gradeFor(score, blocking);
  const worst = axes.find((a) => a.status === "fail") ?? axes.find((a) => a.status === "marginal") ?? null;
  const verdict = !worst ? `Sua conexão supera todas as metas para ${region.label}. Nada aqui vai segurar GTA 6.` : blocking ? `${worst.label} é o bloqueio. Corrija isso primeiro, os outros números mal importam até resolver.` : `Jogável em todo lugar, com ${worst.label.toLowerCase()} logo fora da faixa confortável.`;
